 	int free_skb = 1;

 	BT_DBG("session %p skb %p len %u", session, skb, skb->len);

-	hdr = skb->data[0];
-	skb_pull(skb, 1);
+	hdr = skb_pull_data(skb, 1);
+	if (!hdr)
